// emailService.ts
import emailjs from "emailjs-com";

const sendEmail = async (toEmail: string, subject: string, message: string) => {
  try {
    const response = await emailjs.send(
      process.env.NEXT_PUBLIC_EMAILJS_SERVICE_ID!, // Service ID bạn đã lấy từ EmailJS
      process.env.NEXT_PUBLIC_EMAILJS_TEMPLATE_ID!, // Template ID bạn đã tạo từ EmailJS
      {
        to_email: toEmail,
        subject: subject,
        message: message,
      },
      process.env.NEXT_PUBLIC_EMAILJS_PUBLIC_KEY! // User ID bạn lấy từ EmailJS
    );
    console.log("Email sent successfully:", response);
  } catch (error) {
    console.error("Error sending email:", error);
  }
};

export default sendEmail;
